const $ = (s) => document.querySelector(s);
const state = JSON.parse(localStorage.getItem('tomato-state') || '{}');
state.tasks ||= [{ id: Date.now(), text: '整理项目方案', done: false, pomodoros: 0 }, { id: Date.now() + 1, text: '阅读 20 页专业书', done: false, pomodoros: 0 }];
state.settings ||= { focus: 25, short: 5, long: 15, sunEvery: 2, sunEnabled: true, notifications: false };
state.settings.sunEvery ||= 2; state.settings.sunEnabled ??= true; state.settings.notifications ??= false;
state.today ||= { date: new Date().toDateString(), pomodoros: 0, minutes: 0 }; state.history ||= {};
if (state.today.date !== new Date().toDateString()) state.today = { date: new Date().toDateString(), pomodoros: 0, minutes: 0 };
let mode = ['focus', 'short', 'long'].includes(state.activeMode) ? state.activeMode : 'focus';
let remaining = Number.isFinite(state.remaining) ? state.remaining : state.settings[mode] * 60;
let running = false, timer, selectedId = state.selectedId || null, cycles = state.cycles || 0, toastTimer, audioContext, noiseSource;
const circumference = 703.72;
function save(){Object.assign(state,{selectedId,cycles,activeMode:mode,remaining});localStorage.setItem('tomato-state',JSON.stringify(state));}
function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3000);}
function format(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function modeName(){return {focus:'专注时间',short:'短暂休息',long:'长休息'}[mode];}
function setMode(next,fresh=true){clearInterval(timer);running=false;mode=next;if(fresh)remaining=state.settings[mode]*60;document.querySelectorAll('.mode-tab').forEach(b=>{const on=b.dataset.mode===mode;b.classList.toggle('active',on);b.setAttribute('aria-selected',on)});renderTimer();save();}
function renderTimer(){const total=state.settings[mode]*60;$('#timeDisplay').textContent=format(Math.max(0,remaining));$('#modeLabel').textContent=running?modeName():remaining===total?'准备开始':'已暂停';$('#progressRing').style.strokeDashoffset=circumference*(1-Math.max(0,remaining)/total);$('#progressRing').style.stroke=mode==='focus'?'':'#9daa8a';$('#startButton').innerHTML=running?'<span>Ⅱ</span> 暂停':`<span>▶</span> ${mode==='focus'?'开始专注':'开始休息'}`;$('#cycleDots').textContent=Array.from({length:4},(_,i)=>i<cycles%4?'●':'○').join(' ');document.title=running?`${format(remaining)} · ${modeName()} — 番茄`:'番茄 · 专注空间';}
function ring(){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;audioContext ||= new C();const o=audioContext.createOscillator(),g=audioContext.createGain();o.frequency.value=660;g.gain.setValueAtTime(.08,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.6);o.connect(g).connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.6);}
function notify(title,body){ring();if(state.settings.notifications&&'Notification'in window&&Notification.permission==='granted')new Notification(title,{body});}
function showSunReminder(){if(!state.settings.sunEnabled||cycles%state.settings.sunEvery!==0)return;$('#sunModal').classList.remove('hidden');notify('护眼时间到了','离开屏幕，去窗边望向远处和自然光；请不要直视太阳。');}
function finish(){clearInterval(timer);running=false;if(mode==='focus'){cycles++;state.today.pomodoros++;state.today.minutes+=state.settings.focus;const key=new Date().toISOString().slice(0,10);state.history[key]=(state.history[key]||0)+1;const task=state.tasks.find(t=>t.id===selectedId);if(task)task.pomodoros++;const next=cycles%4===0?'long':'short';setMode(next);showToast(next==='long'?'四个番茄完成，开始一次长休息。':'一个番茄完成，休息一下吧。');notify('一个番茄完成',next==='long'?'四轮完成，开始长休息。':'开始短暂休息。');showSunReminder();}else{setMode('focus');showToast('休息结束，准备迎接下一次专注。');notify('休息结束','准备开始下一次专注。');}save();renderTimer();renderCurrent();renderTasks();renderStats();}
function toggleTimer(){if(running){clearInterval(timer);running=false;}else{running=true;timer=setInterval(()=>{remaining--;if(remaining<=0)finish();else{renderTimer();save();}},1000);}renderTimer();save();}
function escapeHtml(value){const d=document.createElement('div');d.textContent=value;return d.innerHTML;}
function renderTasks(){const box=$('#taskList');box.innerHTML='';state.tasks.forEach(task=>{const item=document.createElement('div');item.className='task'+(task.done?' done':'');item.innerHTML=`<input class="check" aria-label="完成${escapeHtml(task.text)}" type="checkbox" ${task.done?'checked':''}><span class="task-name">${escapeHtml(task.text)}</span><span class="task-count">${task.pomodoros} 个番茄</span><button class="choose">${selectedId===task.id?'已选择':'专注此项'}</button><button class="delete" title="删除${escapeHtml(task.text)}">×</button>`;item.querySelector('.check').onchange=()=>{task.done=!task.done;save();renderTasks();renderStats()};item.querySelector('.choose').onclick=()=>{selectedId=task.id;save();renderCurrent();renderTasks();showView('focus')};item.querySelector('.delete').onclick=()=>{state.tasks=state.tasks.filter(t=>t.id!==task.id);if(selectedId===task.id)selectedId=null;save();renderTasks();renderCurrent()};box.append(item)});}
function renderCurrent(){const task=state.tasks.find(t=>t.id===selectedId);$('#currentTaskText').textContent=task?task.text:'选择一项待办，开始专注';$('#todayFocus').textContent=state.today.pomodoros;$('#todayMinutes').textContent=state.today.minutes;}
function renderStats(){$('#summaryPomodoros').textContent=Object.values(state.history).reduce((a,b)=>a+b,0)+state.today.pomodoros;$('#summaryMinutes').textContent=Object.values(state.history).reduce((a,b)=>a+b*state.settings.focus,0)+state.today.minutes;$('#summaryDone').textContent=state.tasks.filter(t=>t.done).length;const chart=$('#barChart'),labels=$('#chartLabels');chart.innerHTML='';labels.innerHTML='';const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=d.toISOString().slice(0,10);days.push({label:['日','一','二','三','四','五','六'][d.getDay()],value:i===0?state.today.pomodoros:(state.history[key]||0)})}const max=Math.max(1,...days.map(d=>d.value));days.forEach((d,i)=>{const bar=document.createElement('div');bar.className='bar'+(i===6?' today':'');bar.style.height=`${Math.max(5,d.value/max*100)}%`;bar.title=`${d.value} 个番茄`;chart.append(bar);const label=document.createElement('span');label.textContent=`周${d.label}`;labels.append(label)});}
function renderSunSetting(){$('#sunEvery').textContent=state.settings.sunEvery;const button=$('#sunToggle');button.textContent=state.settings.sunEnabled?'已开启':'已暂停';button.classList.toggle('off',!state.settings.sunEnabled);button.setAttribute('aria-pressed',String(state.settings.sunEnabled));}
function showView(view){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$(`#${view}View`).classList.add('active');document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#viewTitle').textContent={focus:'专注片刻',tasks:'待办清单',stats:'专注记录'}[view];}
function stopWhiteNoise(){if(noiseSource){noiseSource.stop();noiseSource.disconnect();noiseSource=null;}}
function toggleWhiteNoise(button){if(noiseSource){stopWhiteNoise();button.textContent='〰 白噪音';showToast('白噪音已暂停');return;}const C=window.AudioContext||window.webkitAudioContext;if(!C){showToast('当前浏览器不支持播放环境音');return;}audioContext ||= new C();const buffer=audioContext.createBuffer(1,audioContext.sampleRate*2,audioContext.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;noiseSource=audioContext.createBufferSource();noiseSource.buffer=buffer;noiseSource.loop=true;const gain=audioContext.createGain();gain.gain.value=.055;noiseSource.connect(gain).connect(audioContext.destination);audioContext.resume();noiseSource.start();button.textContent='〰 白噪音 · 播放中';showToast('白噪音正在播放');}
$('#dateLabel').textContent=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>showView(b.dataset.view));document.querySelectorAll('.mode-tab').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
function setFocusScreen(enabled){document.body.classList.toggle('focus-screen',enabled);$('#fullscreenButton').title=enabled?'退出沉浸模式':'进入沉浸模式';$('#fullscreenButton').setAttribute('aria-label',enabled?'退出沉浸模式':'进入沉浸模式');}
$('#startButton').onclick=()=>toggleTimer();$('#resetButton').onclick=()=>setMode(mode);$('#selectTaskButton').onclick=()=>showView('tasks');
$('#addTaskButton').onclick=()=>{$('#taskForm').classList.toggle('hidden');$('#taskInput').focus();};$('#taskForm').onsubmit=e=>{e.preventDefault();const text=$('#taskInput').value.trim();if(!text)return;state.tasks.unshift({id:Date.now(),text,done:false,pomodoros:0});$('#taskInput').value='';$('#taskForm').classList.add('hidden');save();renderTasks();};
document.querySelectorAll('.sound').forEach(b=>b.onclick=()=>{document.querySelectorAll('.sound').forEach(x=>x.classList.toggle('active',x===b));if(b.dataset.sound==='白噪音')toggleWhiteNoise(b);else{stopWhiteNoise();const white=[...document.querySelectorAll('.sound')].find(x=>x.dataset.sound==='白噪音');if(white)white.textContent='〰 白噪音';showToast(`已选择${b.dataset.sound}环境音`);}});
$('#fullscreenButton').onclick=()=>setFocusScreen(!document.body.classList.contains('focus-screen'));$('#exitFocusButton').onclick=()=>setFocusScreen(false);$('#sunToggle').onclick=()=>{state.settings.sunEnabled=!state.settings.sunEnabled;save();renderSunSetting();showToast(state.settings.sunEnabled?'护眼提醒已开启':'护眼提醒已暂停');};
$('#settingsButton').onclick=()=>{$('#focusInput').value=state.settings.focus;$('#shortInput').value=state.settings.short;$('#longInput').value=state.settings.long;$('#sunInput').value=state.settings.sunEvery;$('#notificationInput').checked=state.settings.notifications;$('#settingsModal').classList.remove('hidden');};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(`#${b.dataset.close}`).classList.add('hidden'));$('#sunDoneButton').onclick=()=>$('#sunModal').classList.add('hidden');
$('#settingsForm').onsubmit=async e=>{e.preventDefault();const values={focus:+$('#focusInput').value,short:+$('#shortInput').value,long:+$('#longInput').value,sunEvery:+$('#sunInput').value};if(Object.values(values).some(v=>!Number.isFinite(v)||v<1))return showToast('请输入大于 0 的分钟数。');if($('#notificationInput').checked&&'Notification'in window&&Notification.permission==='default'){const permission=await Notification.requestPermission();state.settings.notifications=permission==='granted';if(permission!=='granted')showToast('浏览器通知未授权，仍会在页面内提醒。');}else state.settings.notifications=$('#notificationInput').checked&&('Notification'in window)&&Notification.permission==='granted';Object.assign(state.settings,values);setMode(mode);save();renderSunSetting();$('#settingsModal').classList.add('hidden');showToast('你的专注节奏已保存。');};
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)&&!document.querySelector('.modal:not(.hidden)')){e.preventDefault();toggleTimer();}if(e.key==='Escape'){if(document.body.classList.contains('focus-screen'))setFocusScreen(false);document.querySelectorAll('.modal').forEach(m=>m.classList.add('hidden'));}});
renderTimer();renderTasks();renderCurrent();renderStats();renderSunSetting();
